<?php
declare(strict_types=1);
class NormativaController extends Controller { public function index(): void { require_role('ADMINISTRADOR'); $s=new Sustancia(); $this->view('normativas/index',['normas'=>(new Normativa())->list(),'sustancias'=>$s->active(),'unidades'=>$s->unidades(),'escalas'=>(new EscalaRiesgo())->list()]); } public function store(): void { require_role('ADMINISTRADOR'); verify_csrf(); $id=(new Normativa())->create(post_text('nombre',180),post_text('pais',80),post_text('institucion',120),post_text('descripcion',2000,false)); audit_log('CREAR_NORMATIVA','normativas',$id,''); flash('success','Normativa registrada.'); redirect(url('normativa')); } public function storeEscala(): void { require_role('ADMINISTRADOR'); verify_csrf(); $sid=post_int('sustancia_id',1,999999); $nid=post_int('normativa_id',1,999999); $uid=post_int('unidad_id',1,999999); if(!(new Sustancia())->unidadOk($sid,$uid)) throw new RuntimeException('La unidad no corresponde a la sustancia.'); $nivel=post_enum('nivel',['BAJO','MODERADO','ALTO','CRITICO']); $desde=post_float('desde',0,999999999); $hastaRaw=trim((string)($_POST['hasta']??'')); $hasta=$hastaRaw===''?null:post_float('hasta',0,999999999); if($hasta!==null && $hasta<=$desde) throw new RuntimeException('El rango hasta debe ser mayor que desde.'); $id=(new EscalaRiesgo())->create($sid,$nid,$uid,$nivel,$desde,$hasta,post_text('accion',1000)); audit_log('CREAR_ESCALA','escalas_riesgo',$id,$nivel); flash('success','Escala registrada.'); redirect(url('normativa')); } }
